        Mod="4 VR mods (auto-update)"; InstallerChildId='forza-horizon-6-grayhorizon-vr'; InstallerConflictProbe='.pcvrhub_grayhorizonfh6_ownership.csv'; GithubRepo="oofz/vrmod-releases"; GithubPrerelease=$true; GithubRepoModSlot="B"; GithubRepoPresenceFile="lufz\vrmod-launcher.exe"; GithubRepoVersionFile="lufz\VERSION"; NoVersionSeed=$true; Description="6DoF, cockpit view"; Author="NALULUNA · lufz · Clark"; Bat="ForzaHorizon6VR\START_INSTALLER.bat"; Color="#16101f"; Accent="#b454d4"
        SteamFolder="ForzaHorizon6"; FallbackPaths=@("C:\XboxGames\Forza Horizon 6\Content", "XBOX:Forza Horizon 6"); DurableInstallRoots=@("C:\Games\Forza Horizon 6 VR", "D:\Games\Forza Horizon 6 VR", "E:\Games\Forza Horizon 6 VR")
        # One shared installer menu scales to any future fourth/fifth mod.
        # Installed launchers remain separate, but setup is one clear action.
        TwoMods=$true; CombinedModInstaller=$true
        ModAName="NALULUNA"; ModAButtonLabel="NALULUNA"; ModASub="NALULUNA"; ModALaunch="fh6vr.exe"; ModAProbeFile="NALULUNA\fh6vr.exe"; ModAInstallerChoice="naluluna"
        ModBName="lufz"; ModBButtonLabel="lufz"; ModBSub="lufz"; ModBLaunch="vrmod-launcher.exe"; ModBProbeFile="lufz\vrmod-launcher.exe"; ModBInstallerChoice="lufz"
        ModCName="CheekyRender"; ModCButtonLabel="Cheeky"; ModCSub="CheekyRender"; ModCLaunch="CheekyRender.exe"; ModCProbeFile="CheekyRender\CheekyRender.exe"; ModCInstallerChoice="cheeky"
        GithubRepoB="ClarkCheekyKent/cheeky-render-releases"; GithubRepoBPrerelease=$true; GithubRepoBModSlot="C"; GithubRepoBPresenceFile="CheekyRender\CheekyRender.exe"; GithubRepoBVersionFile=".pcvrhub_version_b"
        # All packages live outside the retail game. NALULUNA's remover
        # verifies its copied dxgi.dll against fh6vrhook.dll before touching
        # it. lufz and CheekyRender both expose an author-provided uninstall
        # action; the Hub verifies their game deployment before removing only
        # the separately extracted launcher payload.
        UninstallExe       = @("UNINSTALL.bat", "UNINSTALL.bat", "UNINSTALL.bat")
        UninstallLabel     = @("Remove NALULUNA", "Remove lufz", "Remove CheekyRender")
        UninstallTargetMod = @("ModA", "ModB", "ModC")
        UninstallArguments = @("-Mod naluluna -HubConfirmed", "-Mod lufz -HubConfirmed", "-Mod cheeky -HubConfirmed")
        UninstallProbeFile = @("NALULUNA\fh6vr.exe", "lufz\vrmod-launcher.exe", "CheekyRender\CheekyRender.exe")
        UninstallSteps = @(
            "Use Uninstall now beside this guide. The Hub shows NALULUNA, lufz and CheekyRender separately and removes only the selected package.",
            "NALULUNA's game-folder dxgi.dll is removed only when it is byte-identical to that installation's fh6vrhook.dll; an unrelated DXGI wrapper is never touched.",
            "For lufz or CheekyRender, complete the author's Uninstall action first and close the launcher. The Hub verifies the selected DXGI deployment before removing its launcher package.",
            "All VR packages live under C:\Games\Forza Horizon 6 VR by default. The retail game, saves, launcher settings and unrelated files are preserved.",
            "No Flat / VR file switch is needed: Start in VR uses the selected external launcher; Open in Steam starts the original game normally."
        )
        InfoUrl="https://ko-fi.com/s/03bdcc5fe9"; Tags=@("forza horizon 6", "forza", "fh6", "naluluna", "lufz", "cheekyrender", "clark cheeky kent", "grayhorizon", "racing", "driving", "open world", "arcade racing", "sim", "simulation")
    },
    @{ Controls="GP"; Title="Ghost of Tsushima VR"; VideoUrl="https://www.youtube.com/watch?v=L7NIei0xkEs"; Quip="Stand on Tsushima's wind-swept fields. The Ghost rides."; SteamId="2215430";            Mod="R.E.A.L."; SteamFolder="Ghost of Tsushima DIRECTOR'S CUT"; Description="KB&M or Gamepad VR"; Author="Luke Ross"; Bat="LukeRossVR\LukeRossVR-core.ps1"; Color="#1a1700"; Accent="#aa3333"; InfoUrl="https://www.patreon.com/realvr"; Tags=@("luke ross, ghost of tsushima", "action", "open world", "rpg", "story") ; ModFile="RealRepo\RealVR64.dll"; ModFileAlt="RealRepo_\RealVR64.dll" },
    @{ Wip=$true; 
        # VRGP, not GP: the mod turns the Touch controllers into an
        # EMULATED GAMEPAD (sticks, triggers, grips, buttons). No physical pad
        # is needed - but it is not motion control, and the author insists it
        # must not be described as such.
        Controls    = "VRGP"
        Title       = "Ghost Recon Wildlands VR"
        # Real VR footage exists now, so the strip says "Watch VR gameplay"
        # again - no VideoLabel override here.
        VideoUrl    = "https://www.youtube.com/watch?v=223zZ8ysFcw"
        Quip        = "Sync up, Ghosts - Bolivia in stereo."
        SteamId     = "460930"
        Mod         = "GRW-XR (auto-update)"
        # Every build so far is an alpha, so the newest release has to be
        # taken including prereleases - /releases/latest would skip them.
        GithubRepo  = "Firejumper93/GhostReconWildlandsVR"
        GithubPrerelease = $true
        Description = "Test build, known bug"
        Author      = "Firejumper93"
        Notice      = "The September 15, 2026 game update is newer than GRW-XR v0.11.1 and is not supported by that build. Setup option 1 keeps following prereleases for a future compatible update. Option 2 creates a separate, pinned Steam build 24821571 with pinned GRW-XR v0.11.1; it contains the English or German base campaign, not paid DLC. Use the mod only for solo campaign or private co-op and never for public matchmaking."
        Bat         = "GhostReconWildlandsVR\START_INSTALLER.bat"
        Color       = "#0d1206"
        Accent      = "#9ab545"
        InfoUrl     = "https://github.com/Firejumper93/GhostReconWildlandsVR"
        ModPageUrl  = "https://github.com/Firejumper93/GhostReconWildlandsVR"
        DownloadUrl = "https://github.com/Firejumper93/GhostReconWildlandsVR/releases"
        # A dxgi.dll search-order proxy next to GRW.exe - no launcher, the
        # game starts through Steam as always and the mod loads itself.
        # Renaming dxgi.dll is the mod's own documented off switch, so the
        # Hub's Flat/VR button uses exactly that pair.
        GameExe        = "GRW.exe"
        
        ModFile        = "dxgi.dll"
        ModFileAlt     = "dxgi.dll.off"
        FlatVREnabled  = "dxgi.dll"
        FlatVRDisabled = "dxgi.dll.off"
        VrInstallEvidence = @("openxr_loader.dll", "dxgi_real.dll", ".pcvrhub_grwxr_ownership.csv")
        CurrentRequiredFile = @("openxr_loader.dll", "dxgi_real.dll", ".pcvrhub_grwxr_ownership.csv")
        DualMode = $true
        CurrentRouteUpdate = $true
        CurrentButtonLabel = "Current"
        DepotButtonLabel = "Build 24821571"
        DepotPath = "C:\Games\Ghost Recon Wildlands VR 24821571"
        DepotInstalledPathFile = ".installed_path_depot"
        DepotRequiredFile = @("openxr_loader.dll", "dxgi_real.dll", ".pcvrhub_grwxr_ownership.csv", ".pcvrhub_grw_depot_24821571", ".pcvrhub_grw_depot_stack", "steam_appid.txt")
        DepotLaunchExe = "Start Ghost Recon Wildlands VR Depot.bat"
        DepotWorkingDirectory = ""
        DepotSteamAppIdFile = "steam_appid.txt"
        LaunchExe = "GRW.exe"
        SteamLaunchForSteamInstall = $true
        UninstallExe       = "UNINSTALL.bat"
        UninstallLabel     = "Remove GRW-XR"
        UninstallProbeFile = ".pcvrhub_grwxr_ownership.csv"
        UninstallRequireProbe = $true
        SteamFolder = "Wildlands"
        # UBISOFT CONNECT TOO SINCE v0.7.0-alpha. The 0.5.0 caveat
        # ("Steam only, other stores are a different exe") is gone: after
        # Ubisoft's August 2026 patch, Steam and Ubisoft Connect ship a
        # BYTE-IDENTICAL GRW.exe and one offset table covers both. Epic
        # stays out - the author says nothing about it.
        FallbackPaths=@("STEAM:Wildlands", "UBI:Tom Clancy's Ghost Recon Wildlands")
        UninstallSteps = @(
            "Close the game.",
            "Use Uninstall now beside this guide. It reads the Hub ownership manifest and asks which independent route to change when Current and Build 24821571 both exist.",
            "Only want to play flat for a while? Do NOT uninstall - use the Flat / VR switch on this page, which renames dxgi.dll for you.",
            "Only unchanged Hub-owned files are removed; a proxy that existed before installation is restored and changed files are preserved.",
            "The separate build 24821571 game data is retained after removing GRW-XR, so it can be reused. Remove that dedicated folder manually only when you no longer want the historical game copy.",
            "The normal Steam or Ubisoft game, saves and unrelated files remain untouched."
        )
        Tags        = @("ghost recon", "wildlands", "grw", "firejumper93", "openxr", "shooter", "fps", "action", "tactical", "military", "open world", "third person", "stealth", "ubisoft","wip")
    },
    @{ Controls="GP"; Title="Ghosts n Goblins Resurrection VR"; VideoUrl="https://youtu.be/5sgmy9nJqZY?t=4402"; VideoLabel="Watch gameplay"; Quip="Lose your armor in one hit - now in glorious 3D."; SteamId="1375400"; Mod="REF (auto-update)"; SteamFolder="Ghosts n Goblins Resurrection"; FallbackPaths=@("STEAM:GhostsnGoblinsResurrection", "STEAM:Ghosts 'n Goblins Resurrection", "STEAM:Makaimura_GG_RE"); Description="KB`&M or Gamepad VR"; Author="praydog"; GitHubNightly="praydog/REFramework-nightly"; Bat="REFrameworkVR\START_INSTALLER.bat"; GameExe="makaimura_GG_RE.exe"; Color="#0a0a1a"; Accent="#7733aa"; InfoUrl="https://github.com/praydog/REFramework"; Tags=@("ghosts goblins", "reframework", "praydog", "fast paced", "platformer", "arcade", "retro"); ModFile="openxr_loader.dll" },
